INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('kjv','GEN',1,1,'In the beginning God created the heaven and the earth.',NULL),
('kjv','GEN',1,2,'And the earth was without form, and void; and darkness was upon the face of the deep. And the Spirit of God moved upon the face of the waters.',NULL),
('kjv','GEN',1,3,'And God said, Let there be light: and there was light.',NULL),
('kjv','GEN',1,4,'And God saw the light, that it was good: and God divided the light from the darkness.',NULL),
('kjv','GEN',1,5,'And God called the light Day, and the darkness he called Night. And the evening and the morning were the first day.',NULL),
('kjv','GEN',1,6,'And God said, Let there be a firmament in the midst of the waters, and let it divide the waters from the waters.',NULL),
('kjv','GEN',1,7,'And God made the firmament, and divided the waters which were under the firmament from the waters which were above the firmament: and it was so.',NULL),
('kjv','GEN',1,8,'And God called the firmament Heaven. And the evening and the morning were the second day.',NULL),
('kjv','GEN',1,9,'And God said, Let the waters under the heaven be gathered together unto one place, and let the dry land appear: and it was so.',NULL),
('kjv','GEN',1,10,'And God called the dry land Earth; and the gathering together of the waters called he Seas: and God saw that it was good.',NULL),
('kjv','GEN',1,11,'And God said, Let the earth bring forth grass, the herb yielding seed, and the fruit tree yielding fruit after his kind, whose seed is in itself, upon the earth: and it was so.',NULL),
('kjv','GEN',1,12,'And the earth brought forth grass, and herb yielding seed after his kind, and the tree yielding fruit, whose seed was in itself, after his kind: and God saw that it was good.',NULL),
('kjv','GEN',1,13,'And the evening and the morning were the third day.',NULL),
('kjv','GEN',1,14,'And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and years:',NULL),
('kjv','GEN',1,15,'And let them be for lights in the firmament of the heaven to give light upon the earth: and it was so.',NULL),
('kjv','GEN',1,16,'And God made two great lights; the greater light to rule the day, and the lesser light to rule the night: he made the stars also.',NULL),
('kjv','GEN',1,17,'And God set them in the firmament of the heaven to give light upon the earth,',NULL),
('kjv','GEN',1,18,'And to rule over the day and over the night, and to divide the light from the darkness: and God saw that it was good.',NULL),
('kjv','GEN',1,19,'And the evening and the morning were the fourth day.',NULL),
('kjv','GEN',1,20,'And God said, Let the waters bring forth abundantly the moving creature that hath life, and fowl that may fly above the earth in the open firmament of heaven.',NULL),
('kjv','GEN',1,21,'And God created great whales, and every living creature that moveth, which the waters brought forth abundantly, after their kind, and every winged fowl after his kind: and God saw that it was good.',NULL),
('kjv','GEN',1,22,'And God blessed them, saying, Be fruitful, and multiply, and fill the waters in the seas, and let fowl multiply in the earth.',NULL),
('kjv','GEN',1,23,'And the evening and the morning were the fifth day.',NULL),
('kjv','GEN',1,24,'And God said, Let the earth bring forth the living creature after his kind, cattle, and creeping thing, and beast of the earth after his kind: and it was so.',NULL),
('kjv','GEN',1,25,'And God made the beast of the earth after his kind, and cattle after their kind, and every thing that creepeth upon the earth after his kind: and God saw that it was good.',NULL),
('kjv','GEN',1,26,'And God said, Let us make man in our image, after our likeness: and let them have dominion over the fish of the sea, and over the fowl of the air, and over the cattle, and over all the earth, and over every creeping thing that creepeth upon the earth.',NULL),
('kjv','GEN',1,27,'So God created man in his own image, in the image of God created he him; male and female created he them.',NULL),
('kjv','GEN',1,28,'And God blessed them, and God said unto them, Be fruitful, and multiply, and replenish the earth, and subdue it: and have dominion over the fish of the sea, and over the fowl of the air, and over every living thing that moveth upon the earth.',NULL),
('kjv','GEN',1,29,'And God said, Behold, I have given you every herb bearing seed, which is upon the face of all the earth, and every tree, in the which is the fruit of a tree yielding seed; to you it shall be for meat.',NULL),
('kjv','GEN',1,30,'And to every beast of the earth, and to every fowl of the air, and to every thing that creepeth upon the earth, wherein there is life, I have given every green herb for meat: and it was so.',NULL),
('kjv','GEN',1,31,'And God saw every thing that he had made, and, behold, it was very good. And the evening and the morning were the sixth day.',NULL),
('kjv','GEN',2,1,'Thus the heavens and the earth were finished, and all the host of them.',NULL),
('kjv','GEN',2,2,'And on the seventh day God ended his work which he had made; and he rested on the seventh day from all his work which he had made.',NULL),
('kjv','GEN',2,3,'And God blessed the seventh day, and sanctified it: because that in it he had rested from all his work which God created and made.',NULL),
('kjv','GEN',2,4,'These are the generations of the heavens and of the earth when they were created, in the day that the LORD God made the earth and the heavens,',NULL),
('kjv','GEN',2,5,'And every plant of the field before it was in the earth, and every herb of the field before it grew: for the LORD God had not caused it to rain upon the earth, and there was not a man to till the ground.',NULL),
('kjv','GEN',2,6,'But there went up a mist from the earth, and watered the whole face of the ground.',NULL),
('kjv','GEN',2,7,'And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul.',NULL),
('kjv','GEN',2,8,'And the LORD God planted a garden eastward in Eden; and there he put the man whom he had formed.',NULL),
('kjv','GEN',2,9,'And out of the ground made the LORD God to grow every tree that is pleasant to the sight, and good for food; the tree of life also in the midst of the garden, and the tree of knowledge of good and evil.',NULL),
('kjv','GEN',2,10,'And a river went out of Eden to water the garden; and from thence it was parted, and became into four heads.',NULL),
('kjv','GEN',2,11,'The name of the first is Pison: that is it which compasseth the whole land of Havilah, where there is gold;',NULL),
('kjv','GEN',2,12,'And the gold of that land is good: there is bdellium and the onyx stone.',NULL),
('kjv','GEN',2,13,'And the name of the second river is Gihon: the same is it that compasseth the whole land of Ethiopia.',NULL),
('kjv','GEN',2,14,'And the name of the third river is Hiddekel: that is it which goeth toward the east of Assyria. And the fourth river is Euphrates.',NULL),
('kjv','GEN',2,15,'And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it.',NULL),
('kjv','GEN',2,16,'And the LORD God commanded the man, saying, Of every tree of the garden thou mayest freely eat:',NULL),
('kjv','GEN',2,17,'But of the tree of the knowledge of good and evil, thou shalt not eat of it: for in the day that thou eatest thereof thou shalt surely die.',NULL),
('kjv','GEN',2,18,'And the LORD God said, It is not good that the man should be alone; I will make him an help meet for him.',NULL),
('kjv','GEN',2,19,'And out of the ground the LORD God formed every beast of the field, and every fowl of the air; and brought them unto Adam to see what he would call them: and whatsoever Adam called every living creature, that was the name thereof.',NULL),
('kjv','GEN',2,20,'And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him.',NULL),
('kjv','GEN',2,21,'And the LORD God caused a deep sleep to fall upon Adam and he slept: and he took one of his ribs, and closed up the flesh instead thereof;',NULL),
('kjv','GEN',2,22,'And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man.',NULL),
('kjv','GEN',2,23,'And Adam said, This is now bone of my bones, and flesh of my flesh: she shall be called Woman, because she was taken out of Man.',NULL),
('kjv','GEN',2,24,'Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh.',NULL),
('kjv','GEN',2,25,'And they were both naked, the man and his wife, and were not ashamed.',NULL),
('kjv','GEN',50,1,'And Joseph fell upon his father’s face, and wept upon him, and kissed him.',NULL),
('kjv','GEN',50,2,'And Joseph commanded his servants the physicians to embalm his father: and the physicians embalmed Israel.',NULL),
('kjv','GEN',50,3,'And forty days were fulfilled for him; for so are fulfilled the days of those which are embalmed: and the Egyptians mourned for him threescore and ten days.',NULL),
('kjv','GEN',50,4,'And when the days of his mourning were past, Joseph spake unto the house of Pharaoh, saying, If now I have found grace in your eyes, speak, I pray you, in the ears of Pharaoh, saying,',NULL),
('kjv','GEN',50,5,'My father made me swear, saying, Lo, I die: in my grave which I have digged for me in the land of Canaan, there shalt thou bury me. Now therefore let me go up, I pray thee, and bury my father, and I will come again.',NULL),
('kjv','GEN',50,6,'And Pharaoh said, Go up, and bury thy father, according as he made thee swear.',NULL),
('kjv','GEN',50,7,'And Joseph went up to bury his father: and with him went up all the servants of Pharaoh, the elders of his house, and all the elders of the land of Egypt,',NULL),
('kjv','GEN',50,8,'And all the house of Joseph, and his brethren, and his father’s house: only their little ones, and their flocks, and their herds, they left in the land of Goshen.',NULL),
('kjv','GEN',50,9,'And there went up with him both chariots and horsemen: and it was a very great company.',NULL),
('kjv','GEN',50,10,'And they came to the threshingfloor of Atad, which is beyond Jordan, and there they mourned with a great and very sore lamentation: and he made a mourning for his father seven days.',NULL),
('kjv','GEN',50,11,'And when the inhabitants of the land, the Canaanites, saw the mourning in the floor of Atad, they said, This is a grievous mourning to the Egyptians: wherefore the name of it was called Abel-mizraim, which is beyond Jordan.',NULL),
('kjv','GEN',50,12,'And his sons did unto him according as he commanded them:',NULL),
('kjv','GEN',50,13,'For his sons carried him into the land of Canaan, and buried him in the cave of the field of Machpelah, which Abraham bought with the field for a possession of a buryingplace of Ephron the Hittite, before Mamre.',NULL),
('kjv','GEN',50,14,'And Joseph returned into Egypt, he, and his brethren, and all that went up with him to bury his father, after he had buried his father.',NULL),
('kjv','GEN',50,15,'And when Joseph’s brethren saw that their father was dead, they said, Joseph will peradventure hate us, and will certainly requite us all the evil which we did unto him.',NULL),
('kjv','GEN',50,16,'And they sent a messenger unto Joseph, saying, Thy father did command before he died, saying,',NULL),
('kjv','GEN',50,17,'So shall ye say unto Joseph, Forgive, I pray thee now, the trespass of thy brethren, and their sin; for they did unto thee evil: and now, we pray thee, forgive the trespass of the servants of the God of thy father. And Joseph wept when they spake unto him.',NULL),
('kjv','GEN',50,18,'And his brethren also went and fell down before his face; and they said, Behold, we be thy servants.',NULL),
('kjv','GEN',50,19,'And Joseph said unto them, Fear not: for am I in the place of God?',NULL),
('kjv','GEN',50,20,'But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.',NULL),
('kjv','GEN',50,21,'Now therefore fear ye not: I will nourish you, and your little ones. And he comforted them, and spake kindly unto them.',NULL),
('kjv','GEN',50,22,'And Joseph dwelt in Egypt, he, and his father’s house: and Joseph lived an hundred and ten years.',NULL),
('kjv','GEN',50,23,'And Joseph saw Ephraim’s children of the third generation: the children also of Machir the son Manasseh were brought up upon Joseph’s knees.',NULL),
('kjv','GEN',50,24,'And Joseph said unto his brethren, I die: and God will surely visit you, and bring you out of this land unto the land which he sware to Abraham, to Isaac, and to Jacob.',NULL),
('kjv','GEN',50,25,'And Joseph took an oath of the children of Israel, saying, God will surely visit you, and ye shall carry up my bones from hence.',NULL),
('kjv','GEN',50,26,'So Joseph died, being an hundred and ten years old: and they embalmed him, and he was put in a coffin in Egypt.',NULL),
('kjv','EXO',1,1,'Now these are the names of the children of Israel, which came into Egypt; every man and his household came with Jacob.',NULL),
('kjv','EXO',1,2,'Reuben, Simeon, Levi, and Judah,',NULL),
('kjv','EXO',1,3,'Issachar, Zebulun, and Benjamin,',NULL),
('kjv','EXO',1,4,'Dan, and Naphtali, Gad, and Asher.',NULL),
('kjv','EXO',1,5,'And all the souls that came out of the loins of Jacob were seventy souls: for Joseph was in Egypt already.',NULL),
('kjv','EXO',1,6,'And Joseph died, and all his brethren, and all that generation.',NULL),
('kjv','EXO',1,7,'And the children of Israel were fruitful, and increased abundantly, and multiplied, and waxed exceeding mighty; and the land was filled with them.',NULL),
('kjv','EXO',1,8,'Now there arose up a new king over Egypt, which knew not Joseph.',NULL),
('kjv','EXO',1,9,'And he said unto his people, Behold, the people of the children of Israel are more and mightier than we:',NULL),
('kjv','EXO',1,10,'Come on, let us deal wisely with them; lest they multiply, and it come to pass, that, when there falleth out any war, they join also unto our enemies, and fight against us, and so get them up out of the land.',NULL),
('kjv','EXO',1,11,'Therefore they did set over them taskmasters to afflict them with their burdens. And they built for Pharaoh treasure cities, Pithom and Raamses.',NULL),
('kjv','EXO',1,12,'But the more they afflicted them, the more they multiplied and grew. And they were grieved because of the children of Israel.',NULL),
('kjv','EXO',1,13,'And the Egyptians made the children of Israel to serve with rigour:',NULL),
('kjv','EXO',1,14,'And they made their lives bitter with hard bondage, in morter, and in brick, and in all manner of service in the field: all their service, wherein they made them serve, was with rigour.',NULL),
('kjv','EXO',1,15,'And the king of Egypt spake to the Hebrew midwives, of which the name of the one was Shiphrah, and the name of the other Puah:',NULL),
('kjv','EXO',1,16,'And he said, When ye do the office of a midwife to the Hebrew women, and see them upon the stools; if it be a son, then ye shall kill him: but if it be a daughter, then she shall live.',NULL),
('kjv','EXO',1,17,'But the midwives feared God, and did not as the king of Egypt commanded them, but saved the men children alive.',NULL),
('kjv','EXO',1,18,'And the king of Egypt called for the midwives, and said unto them, Why have ye done this thing, and have saved the men children alive?',NULL),
('kjv','EXO',1,19,'And the midwives said unto Pharaoh, Because the Hebrew women are not as the Egyptian women; for they are lively, and are delivered ere the midwives come in unto them.',NULL),
('kjv','EXO',1,20,'Therefore God dealt well with the midwives: and the people multiplied, and waxed very mighty.',NULL),
('kjv','EXO',1,21,'And it came to pass, because the midwives feared God, that he made them houses.',NULL),
('kjv','EXO',1,22,'And Pharaoh charged all his people, saying, Every son that is born ye shall cast into the river, and every daughter ye shall save alive.',NULL),
('kjv','PSA',23,1,'The LORD is my shepherd; I shall not want.',NULL),
('kjv','PSA',23,2,'He maketh me to lie down in green pastures: he leadeth me beside the still waters.',NULL),
('kjv','PSA',23,3,'He restoreth my soul: he leadeth me in the paths of righteousness for his name’s sake.',NULL),
('kjv','PSA',23,4,'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.',NULL),
('kjv','PSA',23,5,'Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over.',NULL),
('kjv','PSA',23,6,'Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever.',NULL),
('kjv','PSA',107,1,'O give thanks unto the LORD, for he is good: for his mercy endureth for ever.',NULL),
('kjv','PSA',107,2,'Let the redeemed of the LORD say so, whom he hath redeemed from the hand of the enemy;',NULL),
('kjv','PSA',107,3,'And gathered them out of the lands, from the east, and from the west, from the north, and from the south.',NULL),
('kjv','PSA',107,4,'They wandered in the wilderness in a solitary way; they found no city to dwell in.',NULL),
('kjv','PSA',107,5,'Hungry and thirsty, their soul fainted in them.',NULL),
('kjv','PSA',107,6,'Then they cried unto the LORD in their trouble, and he delivered them out of their distresses.',NULL),
('kjv','PSA',107,7,'And he led them forth by the right way, that they might go to a city of habitation.',NULL),
('kjv','PSA',107,8,'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!',NULL),
('kjv','PSA',107,9,'For he satisfieth the longing soul, and filleth the hungry soul with goodness.',NULL),
('kjv','PSA',107,10,'Such as sit in darkness and in the shadow of death, being bound in affliction and iron;',NULL),
('kjv','PSA',107,11,'Because they rebelled against the words of God, and contemned the counsel of the most High:',NULL),
('kjv','PSA',107,12,'Therefore he brought down their heart with labour; they fell down, and there was none to help.',NULL),
('kjv','PSA',107,13,'Then they cried unto the LORD in their trouble, and he saved them out of their distresses.',NULL),
('kjv','PSA',107,14,'He brought them out of darkness and the shadow of death, and brake their bands in sunder.',NULL),
('kjv','PSA',107,15,'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!',NULL),
('kjv','PSA',107,16,'For he hath broken the gates of brass, and cut the bars of iron in sunder.',NULL),
('kjv','PSA',107,17,'Fools because of their transgression, and because of their iniquities, are afflicted.',NULL),
('kjv','PSA',107,18,'Their soul abhorreth all manner of meat; and they draw near unto the gates of death.',NULL),
('kjv','PSA',107,19,'Then they cry unto the LORD in their trouble, and he saveth them out of their distresses.',NULL),
('kjv','PSA',107,20,'He sent his word, and healed them, and delivered them from their destructions.',NULL),
('kjv','PSA',107,21,'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!',NULL),
('kjv','PSA',107,22,'And let them sacrifice the sacrifices of thanksgiving, and declare his works with rejoicing.',NULL),
('kjv','PSA',107,23,'They that go down to the sea in ships, that do business in great waters;',NULL),
('kjv','PSA',107,24,'These see the works of the LORD, and his wonders in the deep.',NULL),
('kjv','PSA',107,25,'For he commandeth, and raiseth the stormy wind, which lifteth up the waves thereof.',NULL),
('kjv','PSA',107,26,'They mount up to the heaven, they go down again to the depths: their soul is melted because of trouble.',NULL),
('kjv','PSA',107,27,'They reel to and fro, and stagger like a drunken man, and are at their wit’s end.',NULL),
('kjv','PSA',107,28,'Then they cry unto the LORD in their trouble, and he bringeth them out of their distresses.',NULL),
('kjv','PSA',107,29,'He maketh the storm a calm, so that the waves thereof are still.',NULL),
('kjv','PSA',107,30,'Then are they glad because they be quiet; so he bringeth them unto their desired haven.',NULL),
('kjv','PSA',107,31,'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!',NULL),
('kjv','PSA',107,32,'Let them exalt him also in the congregation of the people, and praise him in the assembly of the elders.',NULL),
('kjv','PSA',107,33,'He turneth rivers into a wilderness, and the watersprings into dry ground;',NULL),
('kjv','PSA',107,34,'A fruitful land into barrenness, for the wickedness of them that dwell therein.',NULL),
('kjv','PSA',107,35,'He turneth the wilderness into a standing water, and dry ground into watersprings.',NULL),
('kjv','PSA',107,36,'And there he maketh the hungry to dwell, that they may prepare a city for habitation;',NULL),
('kjv','PSA',107,37,'And sow the fields, and plant vineyards, which may yield fruits of increase.',NULL),
('kjv','PSA',107,38,'He blesseth them also, so that they are multiplied greatly; and suffereth not their cattle to decrease.',NULL),
('kjv','PSA',107,39,'Again, they are minished and brought low through oppression, affliction, and sorrow.',NULL),
('kjv','PSA',107,40,'He poureth contempt upon princes, and causeth them to wander in the wilderness, where there is no way.',NULL),
('kjv','PSA',107,41,'Yet setteth he the poor on high from affliction, and maketh him families like a flock.',NULL),
('kjv','PSA',107,42,'The righteous shall see it, and rejoice: and all iniquity shall stop her mouth.',NULL),
('kjv','PSA',107,43,'Whoso is wise, and will observe these things, even they shall understand the lovingkindness of the LORD.',NULL),
('kjv','PSA',117,1,'O praise the LORD, all ye nations: praise him, all ye people.',NULL),
('kjv','PSA',117,2,'For his merciful kindness is great toward us: and the truth of the LORD endureth for ever. Praise ye the LORD.',NULL),
('kjv','PSA',119,1,'Blessed are the undefiled in the way, who walk in the law of the LORD.',NULL),
('kjv','PSA',119,2,'Blessed are they that keep his testimonies, and that seek him with the whole heart.',NULL),
('kjv','PSA',119,3,'They also do no iniquity: they walk in his ways.',NULL),
('kjv','PSA',119,4,'Thou hast commanded us to keep thy precepts diligently.',NULL),
('kjv','PSA',119,5,'O that my ways were directed to keep thy statutes!',NULL),
('kjv','PSA',119,6,'Then shall I not be ashamed, when I have respect unto all thy commandments.',NULL),
('kjv','PSA',119,7,'I will praise thee with uprightness of heart, when I shall have learned thy righteous judgments.',NULL),
('kjv','PSA',119,8,'I will keep thy statutes: O forsake me not utterly.',NULL),
('kjv','PSA',119,9,'Wherewithal shall a young man cleanse his way? by taking heed thereto according to thy word.',NULL),
('kjv','PSA',119,10,'With my whole heart have I sought thee: O let me not wander from thy commandments.',NULL),
('kjv','PSA',119,11,'Thy word have I hid in mine heart, that I might not sin against thee.',NULL),
('kjv','PSA',119,12,'Blessed art thou, O LORD: teach me thy statutes.',NULL),
('kjv','PSA',119,13,'With my lips have I declared all the judgments of thy mouth.',NULL),
('kjv','PSA',119,14,'I have rejoiced in the way of thy testimonies, as much as in all riches.',NULL),
('kjv','PSA',119,15,'I will meditate in thy precepts, and have respect unto thy ways.',NULL),
('kjv','PSA',119,16,'I will delight myself in thy statutes: I will not forget thy word.',NULL),
('kjv','PSA',119,17,'Deal bountifully with thy servant, that I may live, and keep thy word.',NULL),
('kjv','PSA',119,18,'Open thou mine eyes, that I may behold wondrous things out of thy law.',NULL),
('kjv','PSA',119,19,'I am a stranger in the earth: hide not thy commandments from me.',NULL),
('kjv','PSA',119,20,'My soul breaketh for the longing that it hath unto thy judgments at all times.',NULL),
('kjv','PSA',119,21,'Thou hast rebuked the proud that are cursed, which do err from thy commandments.',NULL),
('kjv','PSA',119,22,'Remove from me reproach and contempt; for I have kept thy testimonies.',NULL),
('kjv','PSA',119,23,'Princes also did sit and speak against me: but thy servant did meditate in thy statutes.',NULL),
('kjv','PSA',119,24,'Thy testimonies also are my delight and my counsellors.',NULL),
('kjv','PSA',119,25,'My soul cleaveth unto the dust: quicken thou me according to thy word.',NULL),
('kjv','PSA',119,26,'I have declared my ways, and thou heardest me: teach me thy statutes.',NULL),
('kjv','PSA',119,27,'Make me to understand the way of thy precepts: so shall I talk of thy wondrous works.',NULL),
('kjv','PSA',119,28,'My soul melteth for heaviness: strengthen thou me according unto thy word.',NULL),
('kjv','PSA',119,29,'Remove from me the way of lying: and grant me thy law graciously.',NULL),
('kjv','PSA',119,30,'I have chosen the way of truth: thy judgments have I laid before me.',NULL),
('kjv','PSA',119,31,'I have stuck unto thy testimonies: O LORD, put me not to shame.',NULL),
('kjv','PSA',119,32,'I will run the way of thy commandments, when thou shalt enlarge my heart.',NULL),
('kjv','PSA',119,33,'Teach me, O LORD, the way of thy statutes; and I shall keep it unto the end.',NULL),
('kjv','PSA',119,34,'Give me understanding, and I shall keep thy law; yea, I shall observe it with my whole heart.',NULL),
('kjv','PSA',119,35,'Make me to go in the path of thy commandments; for therein do I delight.',NULL),
('kjv','PSA',119,36,'Incline my heart unto thy testimonies, and not to covetousness.',NULL),
('kjv','PSA',119,37,'Turn away mine eyes from beholding vanity; and quicken thou me in thy way.',NULL),
('kjv','PSA',119,38,'Stablish thy word unto thy servant, who is devoted to thy fear.',NULL),
('kjv','PSA',119,39,'Turn away my reproach which I fear: for thy judgments are good.',NULL),
('kjv','PSA',119,40,'Behold, I have longed after thy precepts: quicken me in thy righteousness.',NULL),
('kjv','PSA',119,41,'Let thy mercies come also unto me, O LORD, even thy salvation, according to thy word.',NULL),
('kjv','PSA',119,42,'So shall I have wherewith to answer him that reproacheth me: for I trust in thy word.',NULL),
('kjv','PSA',119,43,'And take not the word of truth utterly out of my mouth; for I have hoped in thy judgments.',NULL),
('kjv','PSA',119,44,'So shall I keep thy law continually for ever and ever.',NULL),
('kjv','PSA',119,45,'And I will walk at liberty: for I seek thy precepts.',NULL);
INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('kjv','PSA',119,46,'I will speak of thy testimonies also before kings, and will not be ashamed.',NULL),
('kjv','PSA',119,47,'And I will delight myself in thy commandments, which I have loved.',NULL),
('kjv','PSA',119,48,'My hands also will I lift up unto thy commandments, which I have loved; and I will meditate in thy statutes.',NULL),
('kjv','PSA',119,49,'Remember the word unto thy servant, upon which thou hast caused me to hope.',NULL),
('kjv','PSA',119,50,'This is my comfort in my affliction: for thy word hath quickened me.',NULL),
('kjv','PSA',119,51,'The proud have had me greatly in derision: yet have I not declined from thy law.',NULL),
('kjv','PSA',119,52,'I remembered thy judgments of old, O LORD; and have comforted myself.',NULL),
('kjv','PSA',119,53,'Horror hath taken hold upon me because of the wicked that forsake thy law.',NULL),
('kjv','PSA',119,54,'Thy statutes have been my songs in the house of my pilgrimage.',NULL),
('kjv','PSA',119,55,'I have remembered thy name, O LORD, in the night, and have kept thy law.',NULL),
('kjv','PSA',119,56,'This I had, because I kept thy precepts.',NULL),
('kjv','PSA',119,57,'Thou art my portion, O LORD: I have said that I would keep thy words.',NULL),
('kjv','PSA',119,58,'I intreated thy favour with my whole heart: be merciful unto me according to thy word.',NULL),
('kjv','PSA',119,59,'I thought on my ways, and turned my feet unto thy testimonies.',NULL),
('kjv','PSA',119,60,'I made haste, and delayed not to keep thy commandments.',NULL),
('kjv','PSA',119,61,'The bands of the wicked have robbed me: but I have not forgotten thy law.',NULL),
('kjv','PSA',119,62,'At midnight I will rise to give thanks unto thee because of thy righteous judgments.',NULL),
('kjv','PSA',119,63,'I am a companion of all them that fear thee, and of them that keep thy precepts.',NULL),
('kjv','PSA',119,64,'The earth, O LORD, is full of thy mercy: teach me thy statutes.',NULL),
('kjv','PSA',119,65,'Thou hast dealt well with thy servant, O LORD, according unto thy word.',NULL),
('kjv','PSA',119,66,'Teach me good judgment and knowledge: for I have believed thy commandments.',NULL),
('kjv','PSA',119,67,'Before I was afflicted I went astray: but now have I kept thy word.',NULL),
('kjv','PSA',119,68,'Thou art good, and doest good; teach me thy statutes.',NULL),
('kjv','PSA',119,69,'The proud have forged a lie against me: but I will keep thy precepts with my whole heart.',NULL),
('kjv','PSA',119,70,'Their heart is as fat as grease; but I delight in thy law.',NULL),
('kjv','PSA',119,71,'It is good for me that I have been afflicted; that I might learn thy statutes.',NULL),
('kjv','PSA',119,72,'The law of thy mouth is better unto me than thousands of gold and silver.',NULL),
('kjv','PSA',119,73,'Thy hands have made me and fashioned me: give me understanding, that I may learn thy commandments.',NULL),
('kjv','PSA',119,74,'They that fear thee will be glad when they see me; because I have hoped in thy word.',NULL),
('kjv','PSA',119,75,'I know, O LORD, that thy judgments are right, and that thou in faithfulness hast afflicted me.',NULL),
('kjv','PSA',119,76,'Let, I pray thee, thy merciful kindness be for my comfort, according to thy word unto thy servant.',NULL),
('kjv','PSA',119,77,'Let thy tender mercies come unto me, that I may live: for thy law is my delight.',NULL),
('kjv','PSA',119,78,'Let the proud be ashamed; for they dealt perversely with me without a cause: but I will meditate in thy precepts.',NULL),
('kjv','PSA',119,79,'Let those that fear thee turn unto me, and those that have known thy testimonies.',NULL),
('kjv','PSA',119,80,'Let my heart be sound in thy statutes; that I be not ashamed.',NULL),
('kjv','PSA',119,81,'My soul fainteth for thy salvation: but I hope in thy word.',NULL),
('kjv','PSA',119,82,'Mine eyes fail for thy word, saying, When wilt thou comfort me?',NULL),
('kjv','PSA',119,83,'For I am become like a bottle in the smoke; yet do I not forget thy statutes.',NULL),
('kjv','PSA',119,84,'How many are the days of thy servant? when wilt thou execute judgment on them that persecute me?',NULL),
('kjv','PSA',119,85,'The proud have digged pits for me, which are not after thy law.',NULL),
('kjv','PSA',119,86,'All thy commandments are faithful: they persecute me wrongfully; help thou me.',NULL),
('kjv','PSA',119,87,'They had almost consumed me upon earth; but I forsook not thy precepts.',NULL),
('kjv','PSA',119,88,'Quicken me after thy lovingkindness; so shall I keep the testimony of thy mouth.',NULL),
('kjv','PSA',119,89,'For ever, O LORD, thy word is settled in heaven.',NULL),
('kjv','PSA',119,90,'Thy faithfulness is unto all generations: thou hast established the earth, and it abideth.',NULL),
('kjv','PSA',119,91,'They continue this day according to thine ordinances: for all are thy servants.',NULL),
('kjv','PSA',119,92,'Unless thy law had been my delights, I should then have perished in mine affliction.',NULL),
('kjv','PSA',119,93,'I will never forget thy precepts: for with them thou hast quickened me.',NULL),
('kjv','PSA',119,94,'I am thine, save me; for I have sought thy precepts.',NULL),
('kjv','PSA',119,95,'The wicked have waited for me to destroy me: but I will consider thy testimonies.',NULL),
('kjv','PSA',119,96,'I have seen an end of all perfection: but thy commandment is exceeding broad.',NULL),
('kjv','PSA',119,97,'O how love I thy law! it is my meditation all the day.',NULL),
('kjv','PSA',119,98,'Thou through thy commandments hast made me wiser than mine enemies: for they are ever with me.',NULL),
('kjv','PSA',119,99,'I have more understanding than all my teachers: for thy testimonies are my meditation.',NULL),
('kjv','PSA',119,100,'I understand more than the ancients, because I keep thy precepts.',NULL),
('kjv','PSA',119,101,'I have refrained my feet from every evil way, that I might keep thy word.',NULL),
('kjv','PSA',119,102,'I have not departed from thy judgments: for thou hast taught me.',NULL),
('kjv','PSA',119,103,'How sweet are thy words unto my taste! yea, sweeter than honey to my mouth!',NULL),
('kjv','PSA',119,104,'Through thy precepts I get understanding: therefore I hate every false way.',NULL),
('kjv','PSA',119,105,'Thy word is a lamp unto my feet, and a light unto my path.',NULL),
('kjv','PSA',119,106,'I have sworn, and I will perform it, that I will keep thy righteous judgments.',NULL),
('kjv','PSA',119,107,'I am afflicted very much: quicken me, O LORD, according unto thy word.',NULL),
('kjv','PSA',119,108,'Accept, I beseech thee, the freewill offerings of my mouth, O LORD, and teach me thy judgments.',NULL),
('kjv','PSA',119,109,'My soul is continually in my hand: yet do I not forget thy law.',NULL),
('kjv','PSA',119,110,'The wicked have laid a snare for me: yet I erred not from thy precepts.',NULL),
('kjv','PSA',119,111,'Thy testimonies have I taken as an heritage for ever: for they are the rejoicing of my heart.',NULL),
('kjv','PSA',119,112,'I have inclined mine heart to perform thy statutes alway, even unto the end.',NULL),
('kjv','PSA',119,113,'I hate vain thoughts: but thy law do I love.',NULL),
('kjv','PSA',119,114,'Thou art my hiding place and my shield: I hope in thy word.',NULL),
('kjv','PSA',119,115,'Depart from me, ye evildoers: for I will keep the commandments of my God.',NULL),
('kjv','PSA',119,116,'Uphold me according unto thy word, that I may live: and let me not be ashamed of my hope.',NULL),
('kjv','PSA',119,117,'Hold thou me up, and I shall be safe: and I will have respect unto thy statutes continually.',NULL),
('kjv','PSA',119,118,'Thou hast trodden down all them that err from thy statutes: for their deceit is falsehood.',NULL),
('kjv','PSA',119,119,'Thou puttest away all the wicked of the earth like dross: therefore I love thy testimonies.',NULL),
('kjv','PSA',119,120,'My flesh trembleth for fear of thee; and I am afraid of thy judgments.',NULL),
('kjv','PSA',119,121,'I have done judgment and justice: leave me not to mine oppressors.',NULL),
('kjv','PSA',119,122,'Be surety for thy servant for good: let not the proud oppress me.',NULL),
('kjv','PSA',119,123,'Mine eyes fail for thy salvation, and for the word of thy righteousness.',NULL),
('kjv','PSA',119,124,'Deal with thy servant according unto thy mercy, and teach me thy statutes.',NULL),
('kjv','PSA',119,125,'I am thy servant; give me understanding, that I may know thy testimonies.',NULL),
('kjv','PSA',119,126,'It is time for thee, LORD, to work: for they have made void thy law.',NULL),
('kjv','PSA',119,127,'Therefore I love thy commandments above gold; yea, above fine gold.',NULL),
('kjv','PSA',119,128,'Therefore I esteem all thy precepts concerning all things to be right; and I hate every false way.',NULL),
('kjv','PSA',119,129,'Thy testimonies are wonderful: therefore doth my soul keep them.',NULL),
('kjv','PSA',119,130,'The entrance of thy words giveth light; it giveth understanding unto the simple.',NULL),
('kjv','PSA',119,131,'I opened my mouth, and panted: for I longed for thy commandments.',NULL),
('kjv','PSA',119,132,'Look thou upon me, and be merciful unto me, as thou usest to do unto those that love thy name.',NULL),
('kjv','PSA',119,133,'Order my steps in thy word: and let not any iniquity have dominion over me.',NULL),
('kjv','PSA',119,134,'Deliver me from the oppression of man: so will I keep thy precepts.',NULL),
('kjv','PSA',119,135,'Make thy face to shine upon thy servant; and teach me thy statutes.',NULL),
('kjv','PSA',119,136,'Rivers of waters run down mine eyes, because they keep not thy law.',NULL),
('kjv','PSA',119,137,'Righteous art thou, O LORD, and upright are thy judgments.',NULL),
('kjv','PSA',119,138,'Thy testimonies that thou hast commanded are righteous and very faithful.',NULL),
('kjv','PSA',119,139,'My zeal hath consumed me, because mine enemies have forgotten thy words.',NULL),
('kjv','PSA',119,140,'Thy word is very pure: therefore thy servant loveth it.',NULL),
('kjv','PSA',119,141,'I am small and despised: yet do not I forget thy precepts.',NULL),
('kjv','PSA',119,142,'Thy righteousness is an everlasting righteousness, and thy law is the truth.',NULL),
('kjv','PSA',119,143,'Trouble and anguish have taken hold on me: yet thy commandments are my delights.',NULL),
('kjv','PSA',119,144,'The righteousness of thy testimonies is everlasting: give me understanding, and I shall live.',NULL),
('kjv','PSA',119,145,'I cried with my whole heart; hear me, O LORD: I will keep thy statutes.',NULL),
('kjv','PSA',119,146,'I cried unto thee; save me, and I shall keep thy testimonies.',NULL),
('kjv','PSA',119,147,'I prevented the dawning of the morning, and cried: I hoped in thy word.',NULL),
('kjv','PSA',119,148,'Mine eyes prevent the night watches, that I might meditate in thy word.',NULL),
('kjv','PSA',119,149,'Hear my voice according unto thy lovingkindness: O LORD, quicken me according to thy judgment.',NULL),
('kjv','PSA',119,150,'They draw nigh that follow after mischief: they are far from thy law.',NULL),
('kjv','PSA',119,151,'Thou art near, O LORD; and all thy commandments are truth.',NULL),
('kjv','PSA',119,152,'Concerning thy testimonies, I have known of old that thou hast founded them for ever.',NULL),
('kjv','PSA',119,153,'Consider mine affliction, and deliver me: for I do not forget thy law.',NULL),
('kjv','PSA',119,154,'Plead my cause, and deliver me: quicken me according to thy word.',NULL),
('kjv','PSA',119,155,'Salvation is far from the wicked: for they seek not thy statutes.',NULL),
('kjv','PSA',119,156,'Great are thy tender mercies, O LORD: quicken me according to thy judgments.',NULL),
('kjv','PSA',119,157,'Many are my persecutors and mine enemies; yet do I not decline from thy testimonies.',NULL),
('kjv','PSA',119,158,'I beheld the transgressors, and was grieved; because they kept not thy word.',NULL),
('kjv','PSA',119,159,'Consider how I love thy precepts: quicken me, O LORD, according to thy lovingkindness.',NULL),
('kjv','PSA',119,160,'Thy word is true from the beginning: and every one of thy righteous judgments endureth for ever.',NULL),
('kjv','PSA',119,161,'Princes have persecuted me without a cause: but my heart standeth in awe of thy word.',NULL),
('kjv','PSA',119,162,'I rejoice at thy word, as one that findeth great spoil.',NULL),
('kjv','PSA',119,163,'I hate and abhor lying: but thy law do I love.',NULL),
('kjv','PSA',119,164,'Seven times a day do I praise thee because of thy righteous judgments.',NULL),
('kjv','PSA',119,165,'Great peace have they which love thy law: and nothing shall offend them.',NULL),
('kjv','PSA',119,166,'LORD, I have hoped for thy salvation, and done thy commandments.',NULL),
('kjv','PSA',119,167,'My soul hath kept thy testimonies; and I love them exceedingly.',NULL),
('kjv','PSA',119,168,'I have kept thy precepts and thy testimonies: for all my ways are before thee.',NULL),
('kjv','PSA',119,169,'Let my cry come near before thee, O LORD: give me understanding according to thy word.',NULL),
('kjv','PSA',119,170,'Let my supplication come before thee: deliver me according to thy word.',NULL),
('kjv','PSA',119,171,'My lips shall utter praise, when thou hast taught me thy statutes.',NULL),
('kjv','PSA',119,172,'My tongue shall speak of thy word: for all thy commandments are righteousness.',NULL),
('kjv','PSA',119,173,'Let thine hand help me; for I have chosen thy precepts.',NULL),
('kjv','PSA',119,174,'I have longed for thy salvation, O LORD; and thy law is my delight.',NULL),
('kjv','PSA',119,175,'Let my soul live, and it shall praise thee; and let thy judgments help me.',NULL),
('kjv','PSA',119,176,'I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments.',NULL),
('kjv','PRO',3,1,'My son, forget not my law; but let thine heart keep my commandments:',NULL),
('kjv','PRO',3,2,'For length of days, and long life, and peace, shall they add to thee.',NULL),
('kjv','PRO',3,3,'Let not mercy and truth forsake thee: bind them about thy neck; write them upon the table of thine heart:',NULL),
('kjv','PRO',3,4,'So shalt thou find favour and good understanding in the sight of God and man.',NULL),
('kjv','PRO',3,5,'Trust in the LORD with all thine heart; and lean not unto thine own understanding.',NULL),
('kjv','PRO',3,6,'In all thy ways acknowledge him, and he shall direct thy paths.',NULL),
('kjv','PRO',3,7,'Be not wise in thine own eyes: fear the LORD, and depart from evil.',NULL),
('kjv','PRO',3,8,'It shall be health to thy navel, and marrow to thy bones.',NULL),
('kjv','PRO',3,9,'Honour the LORD with thy substance, and with the firstfruits of all thine increase:',NULL),
('kjv','PRO',3,10,'So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.',NULL),
('kjv','PRO',3,11,'My son, despise not the chastening of the LORD; neither be weary of his correction:',NULL),
('kjv','PRO',3,12,'For whom the LORD loveth he correcteth; even as a father the son in whom he delighteth.',NULL),
('kjv','PRO',3,13,'Happy is the man that findeth wisdom, and the man that getteth understanding.',NULL),
('kjv','PRO',3,14,'For the merchandise of it is better than the merchandise of silver, and the gain thereof than fine gold.',NULL),
('kjv','PRO',3,15,'She is more precious than rubies: and all the things thou canst desire are not to be compared unto her.',NULL),
('kjv','PRO',3,16,'Length of days is in her right hand; and in her left hand riches and honour.',NULL),
('kjv','PRO',3,17,'Her ways are ways of pleasantness, and all her paths are peace.',NULL),
('kjv','PRO',3,18,'She is a tree of life to them that lay hold upon her: and happy is every one that retaineth her.',NULL),
('kjv','PRO',3,19,'The LORD by wisdom hath founded the earth; by understanding hath he established the heavens.',NULL),
('kjv','PRO',3,20,'By his knowledge the depths are broken up, and the clouds drop down the dew.',NULL),
('kjv','PRO',3,21,'My son, let not them depart from thine eyes: keep sound wisdom and discretion:',NULL),
('kjv','PRO',3,22,'So shall they be life unto thy soul, and grace to thy neck.',NULL),
('kjv','PRO',3,23,'Then shalt thou walk in thy way safely, and thy foot shall not stumble.',NULL),
('kjv','PRO',3,24,'When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet.',NULL),
('kjv','PRO',3,25,'Be not afraid of sudden fear, neither of the desolation of the wicked, when it cometh.',NULL),
('kjv','PRO',3,26,'For the LORD shall be thy confidence, and shall keep thy foot from being taken.',NULL),
('kjv','PRO',3,27,'Withhold not good from them to whom it is due, when it is in the power of thine hand to do it.',NULL),
('kjv','PRO',3,28,'Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.',NULL),
('kjv','PRO',3,29,'Devise not evil against thy neighbour, seeing he dwelleth securely by thee.',NULL),
('kjv','PRO',3,30,'Strive not with a man without cause, if he have done thee no harm.',NULL),
('kjv','PRO',3,31,'Envy thou not the oppressor, and choose none of his ways.',NULL),
('kjv','PRO',3,32,'For the froward is abomination to the LORD: but his secret is with the righteous.',NULL),
('kjv','PRO',3,33,'The curse of the LORD is in the house of the wicked: but he blesseth the habitation of the just.',NULL),
('kjv','PRO',3,34,'Surely he scorneth the scorners: but he giveth grace unto the lowly.',NULL),
('kjv','PRO',3,35,'The wise shall inherit glory: but shame shall be the promotion of fools.',NULL),
('kjv','PRO',17,1,'Better is a dry morsel, and quietness therewith, than an house full of sacrifices with strife.',NULL),
('kjv','PRO',17,2,'A wise servant shall have rule over a son that causeth shame, and shall have part of the inheritance among the brethren.',NULL),
('kjv','PRO',17,3,'The fining pot is for silver, and the furnace for gold: but the LORD trieth the hearts.',NULL),
('kjv','PRO',17,4,'A wicked doer giveth heed to false lips; and a liar giveth ear to a naughty tongue.',NULL),
('kjv','PRO',17,5,'Whoso mocketh the poor reproacheth his Maker: and he that is glad at calamities shall not be unpunished.',NULL),
('kjv','PRO',17,6,'Children’s children are the crown of old men; and the glory of children are their fathers.',NULL),
('kjv','PRO',17,7,'Excellent speech becometh not a fool: much less do lying lips a prince.',NULL),
('kjv','PRO',17,8,'A gift is as a precious stone in the eyes of him that hath it: whithersoever it turneth, it prospereth.',NULL),
('kjv','PRO',17,9,'He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends.',NULL),
('kjv','PRO',17,10,'A reproof entereth more into a wise man than an hundred stripes into a fool.',NULL),
('kjv','PRO',17,11,'An evil man seeketh only rebellion: therefore a cruel messenger shall be sent against him.',NULL),
('kjv','PRO',17,12,'Let a bear robbed of her whelps meet a man, rather than a fool in his folly.',NULL),
('kjv','PRO',17,13,'Whoso rewardeth evil for good, evil shall not depart from his house.',NULL),
('kjv','PRO',17,14,'The beginning of strife is as when one letteth out water: therefore leave off contention, before it be meddled with.',NULL),
('kjv','PRO',17,15,'He that justifieth the wicked, and he that condemneth the just, even they both are abomination to the LORD.',NULL),
('kjv','PRO',17,16,'Wherefore is there a price in the hand of a fool to get wisdom, seeing he hath no heart to it?',NULL),
('kjv','PRO',17,17,'A friend loveth at all times, and a brother is born for adversity.',NULL),
('kjv','PRO',17,18,'A man void of understanding striketh hands, and becometh surety in the presence of his friend.',NULL),
('kjv','PRO',17,19,'He loveth transgression that loveth strife: and he that exalteth his gate seeketh destruction.',NULL),
('kjv','PRO',17,20,'He that hath a froward heart findeth no good: and he that hath a perverse tongue falleth into mischief.',NULL),
('kjv','PRO',17,21,'He that begetteth a fool doeth it to his sorrow: and the father of a fool hath no joy.',NULL),
('kjv','PRO',17,22,'A merry heart doeth good like a medicine: but a broken spirit drieth the bones.',NULL),
('kjv','PRO',17,23,'A wicked man taketh a gift out of the bosom to pervert the ways of judgment.',NULL),
('kjv','PRO',17,24,'Wisdom is before him that hath understanding; but the eyes of a fool are in the ends of the earth.',NULL),
('kjv','PRO',17,25,'A foolish son is a grief to his father, and bitterness to her that bare him.',NULL),
('kjv','PRO',17,26,'Also to punish the just is not good, nor to strike princes for equity.',NULL),
('kjv','PRO',17,27,'He that hath knowledge spareth his words: and a man of understanding is of an excellent spirit.',NULL),
('kjv','PRO',17,28,'Even a fool, when he holdeth his peace, is counted wise: and he that shutteth his lips is esteemed a man of understanding.',NULL),
('kjv','PRO',31,1,'The words of king Lemuel, the prophecy that his mother taught him.',NULL),
('kjv','PRO',31,2,'What, my son? and what, the son of my womb? and what, the son of my vows?',NULL),
('kjv','PRO',31,3,'Give not thy strength unto women, nor thy ways to that which destroyeth kings.',NULL),
('kjv','PRO',31,4,'It is not for kings, O Lemuel, it is not for kings to drink wine; nor for princes strong drink:',NULL),
('kjv','PRO',31,5,'Lest they drink, and forget the law, and pervert the judgment of any of the afflicted.',NULL),
('kjv','PRO',31,6,'Give strong drink unto him that is ready to perish, and wine unto those that be of heavy hearts.',NULL);
INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('kjv','PRO',31,7,'Let him drink, and forget his poverty, and remember his misery no more.',NULL),
('kjv','PRO',31,8,'Open thy mouth for the dumb in the cause of all such as are appointed to destruction.',NULL),
('kjv','PRO',31,9,'Open thy mouth, judge righteously, and plead the cause of the poor and needy.',NULL),
('kjv','PRO',31,10,'Who can find a virtuous woman? for her price is far above rubies.',NULL),
('kjv','PRO',31,11,'The heart of her husband doth safely trust in her, so that he shall have no need of spoil.',NULL),
('kjv','PRO',31,12,'She will do him good and not evil all the days of her life.',NULL),
('kjv','PRO',31,13,'She seeketh wool, and flax, and worketh willingly with her hands.',NULL),
('kjv','PRO',31,14,'She is like the merchants’ ships; she bringeth her food from afar.',NULL),
('kjv','PRO',31,15,'She riseth also while it is yet night, and giveth meat to her household, and a portion to her maidens.',NULL),
('kjv','PRO',31,16,'She considereth a field, and buyeth it: with the fruit of her hands she planteth a vineyard.',NULL),
('kjv','PRO',31,17,'She girdeth her loins with strength, and strengtheneth her arms.',NULL),
('kjv','PRO',31,18,'She perceiveth that her merchandise is good: her candle goeth not out by night.',NULL),
('kjv','PRO',31,19,'She layeth her hands to the spindle, and her hands hold the distaff.',NULL),
('kjv','PRO',31,20,'She stretcheth out her hand to the poor; yea, she reacheth forth her hands to the needy.',NULL),
('kjv','PRO',31,21,'She is not afraid of the snow for her household: for all her household are clothed with scarlet.',NULL),
('kjv','PRO',31,22,'She maketh herself coverings of tapestry; her clothing is silk and purple.',NULL),
('kjv','PRO',31,23,'Her husband is known in the gates, when he sitteth among the elders of the land.',NULL),
('kjv','PRO',31,24,'She maketh fine linen, and selleth it; and delivereth girdles unto the merchant.',NULL),
('kjv','PRO',31,25,'Strength and honour are her clothing; and she shall rejoice in time to come.',NULL),
('kjv','PRO',31,26,'She openeth her mouth with wisdom; and in her tongue is the law of kindness.',NULL),
('kjv','PRO',31,27,'She looketh well to the ways of her household, and eateth not the bread of idleness.',NULL),
('kjv','PRO',31,28,'Her children arise up, and call her blessed; her husband also, and he praiseth her.',NULL),
('kjv','PRO',31,29,'Many daughters have done virtuously, but thou excellest them all.',NULL),
('kjv','PRO',31,30,'Favour is deceitful, and beauty is vain: but a woman that feareth the LORD, she shall be praised.',NULL),
('kjv','PRO',31,31,'Give her of the fruit of her hands; and let her own works praise her in the gates.',NULL),
('kjv','JER',29,1,'Now these are the words of the letter that Jeremiah the prophet sent from Jerusalem unto the residue of the elders which were carried away captives, and to the priests, and to the prophets, and to all the people whom Nebuchadnezzar had carried away captive from Jerusalem to Babylon;',NULL),
('kjv','JER',29,2,'(After that Jeconiah the king, and the queen, and the eunuchs, the princes of Judah and Jerusalem, and the carpenters, and the smiths, were departed from Jerusalem;)',NULL),
('kjv','JER',29,3,'By the hand of Elasah the son of Shaphan, and Gemariah the son of Hilkiah, (whom Zedekiah king of Judah sent unto Babylon to Nebuchadnezzar king of Babylon) saying,',NULL),
('kjv','JER',29,4,'Thus saith the LORD of hosts, the God of Israel, unto all that are carried away captives, whom I have caused to be carried away from Jerusalem unto Babylon;',NULL),
('kjv','JER',29,5,'Build ye houses, and dwell in them; and plant gardens, and eat the fruit of them;',NULL),
('kjv','JER',29,6,'Take ye wives, and beget sons and daughters; and take wives for your sons, and give your daughters to husbands, that they may bear sons and daughters; that ye may be increased there, and not diminished.',NULL),
('kjv','JER',29,7,'And seek the peace of the city whither I have caused you to be carried away captives, and pray unto the LORD for it: for in the peace thereof shall ye have peace.',NULL),
('kjv','JER',29,8,'For thus saith the LORD of hosts, the God of Israel; Let not your prophets and your diviners, that be in the midst of you, deceive you, neither hearken to your dreams which ye cause to be dreamed.',NULL),
('kjv','JER',29,9,'For they prophesy falsely unto you in my name: I have not sent them, saith the LORD.',NULL),
('kjv','JER',29,10,'For thus saith the LORD, That after seventy years be accomplished at Babylon I will visit you, and perform my good word toward you, in causing you to return to this place.',NULL),
('kjv','JER',29,11,'For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.',NULL),
('kjv','JER',29,12,'Then shall ye call upon me, and ye shall go and pray unto me, and I will hearken unto you.',NULL),
('kjv','JER',29,13,'And ye shall seek me, and find me, when ye shall search for me with all your heart.',NULL),
('kjv','JER',29,14,'And I will be found of you, saith the LORD: and I will turn away your captivity, and I will gather you from all the nations, and from all the places whither I have driven you, saith the LORD; and I will bring you again into the place whence I caused you to be carried away captive.',NULL),
('kjv','JER',29,15,'Because ye have said, The LORD hath raised us up prophets in Babylon;',NULL),
('kjv','JER',29,16,'Know that thus saith the LORD of the king that sitteth upon the throne of David, and of all the people that dwelleth in this city, and of your brethren that are not gone forth with you into captivity;',NULL),
('kjv','JER',29,17,'Thus saith the LORD of hosts; Behold, I will send upon them the sword, the famine, and the pestilence, and will make them like vile figs, that cannot be eaten, they are so evil.',NULL),
('kjv','JER',29,18,'And I will persecute them with the sword, with the famine, and with the pestilence, and will deliver them to be removed to all the kingdoms of the earth, to be a curse, and an astonishment, and an hissing, and a reproach, among all the nations whither I have driven them:',NULL),
('kjv','JER',29,19,'Because they have not hearkened to my words, saith the LORD, which I sent unto them by my servants the prophets, rising up early and sending them; but ye would not hear, saith the LORD.',NULL),
('kjv','JER',29,20,'Hear ye therefore the word of the LORD, all ye of the captivity, whom I have sent from Jerusalem to Babylon:',NULL),
('kjv','JER',29,21,'Thus saith the LORD of hosts, the God of Israel, of Ahab the son of Kolaiah, and of Zedekiah the son of Maaseiah, which prophesy a lie unto you in my name; Behold, I will deliver them into the hand of Nebuchadrezzar king of Babylon; and he shall slay them before your eyes;',NULL),
('kjv','JER',29,22,'And of them shall be taken up a curse by all the captivity of Judah which are in Babylon, saying, The LORD make thee like Zedekiah and like Ahab, whom the king of Babylon roasted in the fire;',NULL),
('kjv','JER',29,23,'Because they have committed villany in Israel, and have committed adultery with their neighbours’ wives, and have spoken lying words in my name, which I have not commanded them; even I know, and am a witness, saith the LORD.',NULL),
('kjv','JER',29,24,'Thus shalt thou also speak to Shemaiah the Nehelamite, saying,',NULL),
('kjv','JER',29,25,'Thus speaketh the LORD of hosts, the God of Israel, saying, Because thou hast sent letters in thy name unto all the people that are at Jerusalem, and to Zephaniah the son of Maaseiah the priest, and to all the priests, saying,',NULL),
('kjv','JER',29,26,'The LORD hath made thee priest in the stead of Jehoiada the priest, that ye should be officers in the house of the LORD, for every man that is mad, and maketh himself a prophet, that thou shouldest put him in prison, and in the stocks.',NULL),
('kjv','JER',29,27,'Now therefore why hast thou not reproved Jeremiah of Anathoth, which maketh himself a prophet to you?',NULL),
('kjv','JER',29,28,'For therefore he sent unto us in Babylon, saying, This captivity is long: build ye houses, and dwell in them; and plant gardens, and eat the fruit of them.',NULL),
('kjv','JER',29,29,'And Zephaniah the priest read this letter in the ears of Jeremiah the prophet.',NULL),
('kjv','JER',29,30,'Then came the word of the LORD unto Jeremiah, saying,',NULL),
('kjv','JER',29,31,'Send to all them of the captivity, saying, Thus saith the LORD concerning Shemaiah the Nehelamite; Because that Shemaiah hath prophesied unto you, and I sent him not, and he caused you to trust in a lie:',NULL),
('kjv','JER',29,32,'Therefore thus saith the LORD; Behold, I will punish Shemaiah the Nehelamite, and his seed: he shall not have a man to dwell among this people; neither shall he behold the good that I will do for my people, saith the LORD; because he hath taught rebellion against the LORD.',NULL),
('kjv','MAL',4,1,'For, behold, the day cometh, that shall burn as an oven; and all the proud, yea, and all that do wickedly, shall be stubble: and the day that cometh shall burn them up, saith the LORD of hosts, that it shall leave them neither root nor branch.',NULL),
('kjv','MAL',4,2,'But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall.',NULL),
('kjv','MAL',4,3,'And ye shall tread down the wicked; for they shall be ashes under the soles of your feet in the day that I shall do this, saith the LORD of hosts.',NULL),
('kjv','MAL',4,4,'Remember ye the law of Moses my servant, which I commanded unto him in Horeb for all Israel, with the statutes and judgments.',NULL),
('kjv','MAL',4,5,'Behold, I will send you Elijah the prophet before the coming of the great and dreadful day of the LORD:',NULL),
('kjv','MAL',4,6,'And he shall turn the heart of the fathers to the children, and the heart of the children to their fathers, lest I come and smite the earth with a curse.',NULL),
('kjv','MAT',1,1,'The book of the generation of Jesus Christ, the son of David, the son of Abraham.',NULL),
('kjv','MAT',1,2,'Abraham begat Isaac; and Isaac begat Jacob; and Jacob begat Judas and his brethren;',NULL),
('kjv','MAT',1,3,'And Judas begat Phares and Zara of Thamar; and Phares begat Esrom; and Esrom begat Aram;',NULL),
('kjv','MAT',1,4,'And Aram begat Aminadab; and Aminadab begat Naasson; and Naasson begat Salmon;',NULL),
('kjv','MAT',1,5,'And Salmon begat Booz of Rachab; and Booz begat Obed of Ruth; and Obed begat Jesse;',NULL),
('kjv','MAT',1,6,'And Jesse begat David the king; and David the king begat Solomon of her that had been the wife of Urias;',NULL),
('kjv','MAT',1,7,'And Solomon begat Roboam; and Roboam begat Abia; and Abia begat Asa;',NULL),
('kjv','MAT',1,8,'And Asa begat Josaphat; and Josaphat begat Joram; and Joram begat Ozias;',NULL),
('kjv','MAT',1,9,'And Ozias begat Joatham; and Joatham begat Achaz; and Achaz begat Ezekias;',NULL),
('kjv','MAT',1,10,'And Ezekias begat Manasses; and Manasses begat Amon; and Amon begat Josias;',NULL),
('kjv','MAT',1,11,'And Josias begat Jechonias and his brethren, about the time they were carried away to Babylon:',NULL),
('kjv','MAT',1,12,'And after they were brought to Babylon, Jechonias begat Salathiel; and Salathiel begat Zorobabel;',NULL),
('kjv','MAT',1,13,'And Zorobabel begat Abiud; and Abiud begat Eliakim; and Eliakim begat Azor;',NULL),
('kjv','MAT',1,14,'And Azor begat Sadoc; and Sadoc begat Achim; and Achim begat Eliud;',NULL),
('kjv','MAT',1,15,'And Eliud begat Eleazar; and Eleazar begat Matthan; and Matthan begat Jacob;',NULL),
('kjv','MAT',1,16,'And Jacob begat Joseph the husband of Mary, of whom was born Jesus, who is called Christ.',NULL),
('kjv','MAT',1,17,'So all the generations from Abraham to David are fourteen generations; and from David until the carrying away into Babylon are fourteen generations; and from the carrying away into Babylon unto Christ are fourteen generations.',NULL),
('kjv','MAT',1,18,'Now the birth of Jesus Christ was on this wise: When as his mother Mary was espoused to Joseph, before they came together, she was found with child of the Holy Ghost.',NULL),
('kjv','MAT',1,19,'Then Joseph her husband, being a just man, and not willing to make her a publick example, was minded to put her away privily.',NULL),
('kjv','MAT',1,20,'But while he thought on these things, behold, the angel of the Lord appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost.',NULL),
('kjv','MAT',1,21,'And she shall bring forth a son, and thou shalt call his name JESUS: for he shall save his people from their sins.',NULL),
('kjv','MAT',1,22,'Now all this was done, that it might be fulfilled which was spoken of the Lord by the prophet, saying,',NULL),
('kjv','MAT',1,23,'Behold, a virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us.',NULL),
('kjv','MAT',1,24,'Then Joseph being raised from sleep did as the angel of the Lord had bidden him, and took unto him his wife:',NULL),
('kjv','MAT',1,25,'And knew her not till she had brought forth her firstborn son: and he called his name JESUS.',NULL),
('kjv','MAT',11,1,'And it came to pass, when Jesus had made an end of commanding his twelve disciples, he departed thence to teach and to preach in their cities.',NULL),
('kjv','MAT',11,2,'Now when John had heard in the prison the works of Christ, he sent two of his disciples,',NULL),
('kjv','MAT',11,3,'And said unto him, Art thou he that should come, or do we look for another?',NULL),
('kjv','MAT',11,4,'Jesus answered and said unto them, Go and shew John again those things which ye do hear and see:','[[35,61]]'),
('kjv','MAT',11,5,'The blind receive their sight, and the lame walk, the lepers are cleansed, and the deaf hear, the dead are raised up, and the poor have the gospel preached to them.','[[0,164]]'),
('kjv','MAT',11,6,'And blessed is he, whosoever shall not be offended in me.','[[0,57]]'),
('kjv','MAT',11,7,'And as they departed, Jesus began to say unto the multitudes concerning John, What went ye out into the wilderness to see? A reed shaken with the wind?','[[78,73]]'),
('kjv','MAT',11,8,'But what went ye out for to see? A man clothed in soft raiment? behold, they that wear soft clothing are in kings’ houses.','[[0,122]]'),
('kjv','MAT',11,9,'But what went ye out for to see? A prophet? yea, I say unto you, and more than a prophet.','[[0,89]]'),
('kjv','MAT',11,10,'For this is he, of whom it is written, Behold, I send my messenger before thy face, which shall prepare thy way before thee.','[[0,124]]'),
('kjv','MAT',11,11,'Verily I say unto you, Among them that are born of women there hath not risen a greater than John the Baptist: notwithstanding he that is least in the kingdom of heaven is greater than he.','[[0,188]]'),
('kjv','MAT',11,12,'And from the days of John the Baptist until now the kingdom of heaven suffereth violence, and the violent take it by force.','[[0,123]]'),
('kjv','MAT',11,13,'For all the prophets and the law prophesied until John.','[[0,55]]'),
('kjv','MAT',11,14,'And if ye will receive it, this is Elias, which was for to come.','[[0,64]]'),
('kjv','MAT',11,15,'He that hath ears to hear, let him hear.','[[0,40]]'),
('kjv','MAT',11,16,'But whereunto shall I liken this generation? It is like unto children sitting in the markets, and calling unto their fellows,','[[0,125]]'),
('kjv','MAT',11,17,'And saying, We have piped unto you, and ye have not danced; we have mourned unto you, and ye have not lamented.','[[0,111]]'),
('kjv','MAT',11,18,'For John came neither eating nor drinking, and they say, He hath a devil.','[[0,73]]'),
('kjv','MAT',11,19,'The Son of man came eating and drinking, and they say, Behold a man gluttonous, and a winebibber, a friend of publicans and sinners. But wisdom is justified of her children.','[[0,173]]'),
('kjv','MAT',11,20,'Then began he to upbraid the cities wherein most of his mighty works were done, because they repented not:',NULL),
('kjv','MAT',11,21,'Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works, which were done in you, had been done in Tyre and Sidon, they would have repented long ago in sackcloth and ashes.','[[0,190]]'),
('kjv','MAT',11,22,'But I say unto you, It shall be more tolerable for Tyre and Sidon at the day of judgment, than for you.','[[0,103]]'),
('kjv','MAT',11,23,'And thou, Capernaum, which art exalted unto heaven, shalt be brought down to hell: for if the mighty works, which have been done in thee, had been done in Sodom, it would have remained until this day.','[[0,200]]'),
('kjv','MAT',11,24,'But I say unto you, That it shall be more tolerable for the land of Sodom in the day of judgment, than for thee.','[[0,112]]'),
('kjv','MAT',11,25,'At that time Jesus answered and said, I thank thee, O Father, Lord of heaven and earth, because thou hast hid these things from the wise and prudent, and hast revealed them unto babes.','[[38,146]]'),
('kjv','MAT',11,26,'Even so, Father: for so it seemed good in thy sight.','[[0,52]]'),
('kjv','MAT',11,27,'All things are delivered unto me of my Father: and no man knoweth the Son, but the Father; neither knoweth any man the Father, save the Son, and he to whomsoever the Son will reveal him.','[[0,185]]'),
('kjv','MAT',11,28,'Come unto me, all ye that labour and are heavy laden, and I will give you rest.','[[0,79]]'),
('kjv','MAT',11,29,'Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls.','[[0,113]]'),
('kjv','MAT',11,30,'For my yoke is easy, and my burden is light.','[[0,44]]'),
('kjv','MAT',17,1,'And after six days Jesus taketh Peter, James, and John his brother, and bringeth them up into an high mountain apart,',NULL),
('kjv','MAT',17,2,'And was transfigured before them: and his face did shine as the sun, and his raiment was white as the light.',NULL),
('kjv','MAT',17,3,'And, behold, there appeared unto them Moses and Elias talking with him.',NULL),
('kjv','MAT',17,4,'Then answered Peter, and said unto Jesus, Lord, it is good for us to be here: if thou wilt, let us make here three tabernacles; one for thee, and one for Moses, and one for Elias.',NULL),
('kjv','MAT',17,5,'While he yet spake, behold, a bright cloud overshadowed them: and behold a voice out of the cloud, which said, This is my beloved Son, in whom I am well pleased; hear ye him.',NULL),
('kjv','MAT',17,6,'And when the disciples heard it, they fell on their face, and were sore afraid.',NULL),
('kjv','MAT',17,7,'And Jesus came and touched them, and said, Arise, and be not afraid.','[[43,25]]'),
('kjv','MAT',17,8,'And when they had lifted up their eyes, they saw no man, save Jesus only.',NULL),
('kjv','MAT',17,9,'And as they came down from the mountain, Jesus charged them, saying, Tell the vision to no man, until the Son of man be risen again from the dead.','[[69,77]]'),
('kjv','MAT',17,10,'And his disciples asked him, saying, Why then say the scribes that Elias must first come?',NULL),
('kjv','MAT',17,11,'And Jesus answered and said unto them, Elias truly shall first come, and restore all things.','[[39,53]]'),
('kjv','MAT',17,12,'But I say unto you, That Elias is come already, and they knew him not, but have done unto him whatsoever they listed. Likewise shall also the Son of man suffer of them.','[[0,168]]'),
('kjv','MAT',17,13,'Then the disciples understood that he spake unto them of John the Baptist.',NULL),
('kjv','MAT',17,14,'And when they were come to the multitude, there came to him a certain man, kneeling down to him, and saying,',NULL),
('kjv','MAT',17,15,'Lord, have mercy on my son: for he is lunatick, and sore vexed: for ofttimes he falleth into the fire, and oft into the water.',NULL),
('kjv','MAT',17,16,'And I brought him to thy disciples, and they could not cure him.',NULL),
('kjv','MAT',17,17,'Then Jesus answered and said, O faithless and perverse generation, how long shall I be with you? how long shall I suffer you? bring him hither to me.','[[30,119]]'),
('kjv','MAT',17,18,'And Jesus rebuked the devil; and he departed out of him: and the child was cured from that very hour.',NULL),
('kjv','MAT',17,19,'Then came the disciples to Jesus apart, and said, Why could not we cast him out?',NULL),
('kjv','MAT',17,20,'And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you.','[[26,223]]'),
('kjv','MAT',17,21,'Howbeit this kind goeth not out but by prayer and fasting.','[[0,58]]'),
('kjv','MAT',17,22,'And while they abode in Galilee, Jesus said unto them, The Son of man shall be betrayed into the hands of men:','[[55,55]]'),
('kjv','MAT',17,23,'And they shall kill him, and the third day he shall be raised again. And they were exceeding sorry.','[[0,68]]'),
('kjv','MAT',17,24,'And when they were come to Capernaum, they that received tribute money came to Peter, and said, Doth not your master pay tribute?',NULL),
('kjv','MAT',17,25,'He saith, Yes. And when he was come into the house, Jesus prevented him, saying, What thinkest thou, Simon? of whom do the kings of the earth take custom or tribute? of their own children, or of strangers?','[[81,124]]'),
('kjv','MAT',17,26,'Peter saith unto him, Of strangers. Jesus saith unto him, Then are the children free.','[[58,27]]'),
('kjv','MAT',17,27,'Notwithstanding, lest we should offend them, go thou to the sea, and cast an hook, and take up the fish that first cometh up; and when thou hast opened his mouth, thou shalt find a piece of money: that take, and give unto them for me and thee.','[[0,243]]'),
('kjv','JHN',3,1,'There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:',NULL),
('kjv','JHN',3,2,'The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him.',NULL),
('kjv','JHN',3,3,'Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.','[[34,94]]'),
('kjv','JHN',3,4,'Nicodemus saith unto him, How can a man be born when he is old? can he enter the second time into his mother’s womb, and be born?',NULL),
('kjv','JHN',3,5,'Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and of the Spirit, he cannot enter into the kingdom of God.','[[16,122]]'),
('kjv','JHN',3,6,'That which is born of the flesh is flesh; and that which is born of the Spirit is spirit.','[[0,89]]'),
('kjv','JHN',3,7,'Marvel not that I said unto thee, Ye must be born again.','[[0,56]]'),
('kjv','JHN',3,8,'The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit.','[[0,173]]'),
('kjv','JHN',3,9,'Nicodemus answered and said unto him, How can these things be?',NULL),
('kjv','JHN',3,10,'Jesus answered and said unto him, Art thou a master of Israel, and knowest not these things?','[[34,58]]'),
('kjv','JHN',3,11,'Verily, verily, I say unto thee, We speak that we do know, and testify that we have seen; and ye receive not our witness.','[[0,121]]'),
('kjv','JHN',3,12,'If I have told you earthly things, and ye believe not, how shall ye believe, if I tell you of heavenly things?','[[0,110]]'),
('kjv','JHN',3,13,'And no man hath ascended up to heaven, but he that came down from heaven, even the Son of man which is in heaven.','[[0,113]]'),
('kjv','JHN',3,14,'And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up:','[[0,95]]'),
('kjv','JHN',3,15,'That whosoever believeth in him should not perish, but have eternal life.','[[0,73]]'),
('kjv','JHN',3,16,'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.','[[0,141]]'),
('kjv','JHN',3,17,'For God sent not his Son into the world to condemn the world; but that the world through him might be saved.','[[0,108]]'),
('kjv','JHN',3,18,'He that believeth on him is not condemned: but he that believeth not is condemned already, because he hath not believed in the name of the only begotten Son of God.','[[0,164]]'),
('kjv','JHN',3,19,'And this is the condemnation, that light is come into the world, and men loved darkness rather than light, because their deeds were evil.','[[0,137]]'),
('kjv','JHN',3,20,'For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved.','[[0,111]]'),
('kjv','JHN',3,21,'But he that doeth truth cometh to the light, that his deeds may be made manifest, that they are wrought in God.','[[0,111]]'),
('kjv','JHN',3,22,'After these things came Jesus and his disciples into the land of Judaea; and there he tarried with them, and baptized.',NULL),
('kjv','JHN',3,23,'And John also was baptizing in Aenon near to Salim, because there was much water there: and they came, and were baptized.',NULL),
('kjv','JHN',3,24,'For John was not yet cast into prison.',NULL),
('kjv','JHN',3,25,'Then there arose a question between some of John’s disciples and the Jews about purifying.',NULL),
('kjv','JHN',3,26,'And they came unto John, and said unto him, Rabbi, he that was with thee beyond Jordan, to whom thou barest witness, behold, the same baptizeth, and all men come to him.',NULL),
('kjv','JHN',3,27,'John answered and said, A man can receive nothing, except it be given him from heaven.',NULL),
('kjv','JHN',3,28,'Ye yourselves bear me witness, that I said, I am not the Christ, but that I am sent before him.',NULL),
('kjv','JHN',3,29,'He that hath the bride is the bridegroom: but the friend of the bridegroom, which standeth and heareth him, rejoiceth greatly because of the bridegroom’s voice: this my joy therefore is fulfilled.',NULL),
('kjv','JHN',3,30,'He must increase, but I must decrease.',NULL),
('kjv','JHN',3,31,'He that cometh from above is above all: he that is of the earth is earthly, and speaketh of the earth: he that cometh from heaven is above all.',NULL),
('kjv','JHN',3,32,'And what he hath seen and heard, that he testifieth; and no man receiveth his testimony.',NULL),
('kjv','JHN',3,33,'He that hath received his testimony hath set to his seal that God is true.',NULL),
('kjv','JHN',3,34,'For he whom God hath sent speaketh the words of God: for God giveth not the Spirit by measure unto him.',NULL),
('kjv','JHN',3,35,'The Father loveth the Son, and hath given all things into his hand.',NULL),
('kjv','JHN',3,36,'He that believeth on the Son hath everlasting life: and he that believeth not the Son shall not see life; but the wrath of God abideth on him.',NULL),
('kjv','JAS',1,1,'James, a servant of God and of the Lord Jesus Christ, to the twelve tribes which are scattered abroad, greeting.',NULL),
('kjv','JAS',1,2,'My brethren, count it all joy when ye fall into divers temptations;',NULL),
('kjv','JAS',1,3,'Knowing this, that the trying of your faith worketh patience.',NULL),
('kjv','JAS',1,4,'But let patience have her perfect work, that ye may be perfect and entire, wanting nothing.',NULL),
('kjv','JAS',1,5,'If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.',NULL),
('kjv','JAS',1,6,'But let him ask in faith, nothing wavering. For he that wavereth is like a wave of the sea driven with the wind and tossed.',NULL),
('kjv','JAS',1,7,'For let not that man think that he shall receive any thing of the Lord.',NULL),
('kjv','JAS',1,8,'A double minded man is unstable in all his ways.',NULL),
('kjv','JAS',1,9,'Let the brother of low degree rejoice in that he is exalted:',NULL),
('kjv','JAS',1,10,'But the rich, in that he is made low: because as the flower of the grass he shall pass away.',NULL),
('kjv','JAS',1,11,'For the sun is no sooner risen with a burning heat, but it withereth the grass, and the flower thereof falleth, and the grace of the fashion of it perisheth: so also shall the rich man fade away in his ways.',NULL),
('kjv','JAS',1,12,'Blessed is the man that endureth temptation: for when he is tried, he shall receive the crown of life, which the Lord hath promised to them that love him.',NULL),
('kjv','JAS',1,13,'Let no man say when he is tempted, I am tempted of God: for God cannot be tempted with evil, neither tempteth he any man:',NULL),
('kjv','JAS',1,14,'But every man is tempted, when he is drawn away of his own lust, and enticed.',NULL),
('kjv','JAS',1,15,'Then when lust hath conceived, it bringeth forth sin: and sin, when it is finished, bringeth forth death.',NULL),
('kjv','JAS',1,16,'Do not err, my beloved brethren.',NULL),
('kjv','JAS',1,17,'Every good gift and every perfect gift is from above, and cometh down from the Father of lights, with whom is no variableness, neither shadow of turning.',NULL),
('kjv','JAS',1,18,'Of his own will begat he us with the word of truth, that we should be a kind of firstfruits of his creatures.',NULL),
('kjv','JAS',1,19,'Wherefore, my beloved brethren, let every man be swift to hear, slow to speak, slow to wrath:',NULL);
INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('kjv','JAS',1,20,'For the wrath of man worketh not the righteousness of God.',NULL),
('kjv','JAS',1,21,'Wherefore lay apart all filthiness and superfluity of naughtiness, and receive with meekness the engrafted word, which is able to save your souls.',NULL),
('kjv','JAS',1,22,'But be ye doers of the word, and not hearers only, deceiving your own selves.',NULL),
('kjv','JAS',1,23,'For if any be a hearer of the word, and not a doer, he is like unto a man beholding his natural face in a glass:',NULL),
('kjv','JAS',1,24,'For he beholdeth himself, and goeth his way, and straightway forgetteth what manner of man he was.',NULL),
('kjv','JAS',1,25,'But whoso looketh into the perfect law of liberty, and continueth therein, he being not a forgetful hearer, but a doer of the work, this man shall be blessed in his deed.',NULL),
('kjv','JAS',1,26,'If any man among you seem to be religious, and bridleth not his tongue, but deceiveth his own heart, this man’s religion is vain.',NULL),
('kjv','JAS',1,27,'Pure religion and undefiled before God and the Father is this, To visit the fatherless and widows in their affliction, and to keep himself unspotted from the world.',NULL),
('kjv','3JN',1,1,'The elder unto the wellbeloved Gaius, whom I love in the truth.',NULL),
('kjv','3JN',1,2,'Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.',NULL),
('kjv','3JN',1,3,'For I rejoiced greatly, when the brethren came and testified of the truth that is in thee, even as thou walkest in the truth.',NULL),
('kjv','3JN',1,4,'I have no greater joy than to hear that my children walk in truth.',NULL),
('kjv','3JN',1,5,'Beloved, thou doest faithfully whatsoever thou doest to the brethren, and to strangers;',NULL),
('kjv','3JN',1,6,'Which have borne witness of thy charity before the church: whom if thou bring forward on their journey after a godly sort, thou shalt do well:',NULL),
('kjv','3JN',1,7,'Because that for his name’s sake they went forth, taking nothing of the Gentiles.',NULL),
('kjv','3JN',1,8,'We therefore ought to receive such, that we might be fellowhelpers to the truth.',NULL),
('kjv','3JN',1,9,'I wrote unto the church: but Diotrephes, who loveth to have the preeminence among them, receiveth us not.',NULL),
('kjv','3JN',1,10,'Wherefore, if I come, I will remember his deeds which he doeth, prating against us with malicious words: and not content therewith, neither doth he himself receive the brethren, and forbiddeth them that would, and casteth them out of the church.',NULL),
('kjv','3JN',1,11,'Beloved, follow not that which is evil, but that which is good. He that doeth good is of God: but he that doeth evil hath not seen God.',NULL),
('kjv','3JN',1,12,'Demetrius hath good report of all men, and of the truth itself: yea, and we also bear record; and ye know that our record is true.',NULL),
('kjv','3JN',1,13,'I had many things to write, but I will not with ink and pen write unto thee:',NULL),
('kjv','3JN',1,14,'But I trust I shall shortly see thee, and we shall speak face to face. Peace be to thee. Our friends salute thee. Greet the friends by name.',NULL),
('kjv','REV',22,1,'And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb.',NULL),
('kjv','REV',22,2,'In the midst of the street of it, and on either side of the river, was there the tree of life, which bare twelve manner of fruits, and yielded her fruit every month: and the leaves of the tree were for the healing of the nations.',NULL),
('kjv','REV',22,3,'And there shall be no more curse: but the throne of God and of the Lamb shall be in it; and his servants shall serve him:',NULL),
('kjv','REV',22,4,'And they shall see his face; and his name shall be in their foreheads.',NULL),
('kjv','REV',22,5,'And there shall be no night there; and they need no candle, neither light of the sun; for the Lord God giveth them light: and they shall reign for ever and ever.',NULL),
('kjv','REV',22,6,'And he said unto me, These sayings are faithful and true: and the Lord God of the holy prophets sent his angel to shew unto his servants the things which must shortly be done.',NULL),
('kjv','REV',22,7,'Behold, I come quickly: blessed is he that keepeth the sayings of the prophecy of this book.','[[0,92]]'),
('kjv','REV',22,8,'And I John saw these things, and heard them. And when I had heard and seen, I fell down to worship before the feet of the angel which shewed me these things.',NULL),
('kjv','REV',22,9,'Then saith he unto me, See thou do it not: for I am thy fellowservant, and of thy brethren the prophets, and of them which keep the sayings of this book: worship God.',NULL),
('kjv','REV',22,10,'And he saith unto me, Seal not the sayings of the prophecy of this book: for the time is at hand.',NULL),
('kjv','REV',22,11,'He that is unjust, let him be unjust still: and he which is filthy, let him be filthy still: and he that is righteous, let him be righteous still: and he that is holy, let him be holy still.',NULL),
('kjv','REV',22,12,'And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be.','[[0,104]]'),
('kjv','REV',22,13,'I am Alpha and Omega, the beginning and the end, the first and the last.','[[0,72]]'),
('kjv','REV',22,14,'Blessed are they that do his commandments, that they may have right to the tree of life, and may enter in through the gates into the city.',NULL),
('kjv','REV',22,15,'For without are dogs, and sorcerers, and whoremongers, and murderers, and idolaters, and whosoever loveth and maketh a lie.',NULL),
('kjv','REV',22,16,'I Jesus have sent mine angel to testify unto you these things in the churches. I am the root and the offspring of David, and the bright and morning star.','[[0,153]]'),
('kjv','REV',22,17,'And the Spirit and the bride say, Come. And let him that heareth say, Come. And let him that is athirst come. And whosoever will, let him take the water of life freely.',NULL),
('kjv','REV',22,18,'For I testify unto every man that heareth the words of the prophecy of this book, If any man shall add unto these things, God shall add unto him the plagues that are written in this book:',NULL),
('kjv','REV',22,19,'And if any man shall take away from the words of the book of this prophecy, God shall take away his part out of the book of life, and out of the holy city, and from the things which are written in this book.',NULL),
('kjv','REV',22,20,'He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus.','[[40,22]]'),
('kjv','REV',22,21,'The grace of our Lord Jesus Christ be with you all. Amen.',NULL);
INSERT INTO chapter_titles (translation_id, book_id, chapter, text) VALUES
('kjv','PSA',23,'A Psalm of David.');
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
